def localized_concept(concept_id: str, concept: dict[str, Any], language: str) -> dict[str, Any]:
    """Return a copy, never mutate the shared curriculum registry."""
    result = deepcopy(concept)
    if language != "ar":
        return result
    translation = AR_CONCEPTS.get(concept_id)
    if not translation:
        return result
    for key in ("name", "explain", "analogy", "example", "reflect"):
        if key in translation:
            result[key] = translation[key]
    if "questions" in translation:
        translated = translation["questions"]
        result["questions"] = [
            {**question, **translated[index]} if index < len(translated) else question
            for index, question in enumerate(result.get("questions", []))
        ]
    return result


def localized_question(concept_id: str, question: dict[str, Any], language: str, index: int | None = None) -> dict[str, Any]:
    if language != "ar" or concept_id not in AR_CONCEPTS:
        return deepcopy(question)
    translations = AR_CONCEPTS[concept_id].get("questions", [])
    if index is None or not 0 <= index < len(translations):
        return deepcopy(question)
    result = deepcopy(question)
    result.update(translations[index])
    return result


def has_translation(concept_id: str) -> bool:
    return concept_id in AR_CONCEPTS
